const PICK = ['etag', 'last-modified', 'content-length', 'content-disposition', 'content-type'];

async function hop(url: string, method: string) {
	const hops: string[] = [];
	for (let i = 0; i < 10; i++) {
		const response = await fetch(url, { method, redirect: 'manual', headers: method === 'GET' ? { Range: 'bytes=0-0' } : {}, signal: AbortSignal.timeout(8_000) });
		await response.body?.cancel();
		const location = response.headers.get('location');
		if (location && response.status >= 300 && response.status < 400) {
			url = new URL(location, url).href;
			hops.push(url);
			continue;
		}
		return { status: response.status, hops, headers: Object.fromEntries(PICK.map((k) => [k, response.headers.get(k)]).filter(([, v]) => v)) };
	}
	return { status: 0, hops, headers: {} };
}

async function probe(e: (typeof ENTRIES)[number]) {
	const results = [];
	for (const url of e.urls) {
		const r: Record<string, unknown> = { url };
		for (const method of ['HEAD', 'GET']) {
			if (method === 'GET' && (r.HEAD as { headers?: Record<string, string> })?.headers?.etag) continue;
			try {
				r[method] = await hop(url, method);
			} catch (error) {
				r[method] = { error: String(error) };
			}
		}
		results.push(r);
	}
	console.log(`PROBE ${JSON.stringify({ src: e.src, id: e.id, results })}`);
}

export default defineShard(async () => {
	const queue = [...ENTRIES];
	await Promise.all(Array.from({ length: 48 }, async () => {
		for (let e = queue.shift(); e; e = queue.shift()) await probe(e);
	}));
	throw new Error('probe finished');
});
